from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_root(x_token: str = Header(None)):
    return {"x_token": x_token}

client = TestClient(app)

def test_underscore_header_accepted():
    # Current behavior: x_token (parameter) -> x-token (alias)
    # If we send x-token, it should be accepted.
    response = client.get("/", headers={"x-token": "foo"})
    print(f"x-token: {response.json()}")
    assert response.json() == {"x_token": "foo"}

    # If we send x_token, it should currently be accepted because of how starlette Headers works?
    # Or maybe it's not accepted?
    response = client.get("/", headers={"x_token": "bar"})
    print(f"x_token: {response.json()}")
    # The issue says "Do not accept underscore headers when using convert_underscores=True"
    # This implies it IS currently accepted.
    assert response.json() == {"x_token": "bar"}

def test_underscore_header_not_accepted_when_disabled():
    # If we disable convert_underscores, it should only accept x_token
    # Wait, if convert_underscores=False, it should NOT convert x_token to x-token.
    # So it should only accept x_token.

    # Let's define another endpoint for this
    @app.get("/no-convert")
    async def read_root_no_convert(x_token: str = Header(None, convert_underscores=False)):
        return {"x_token": x_token}

    # Should accept x_token
    response = client.get("/no-convert", headers={"x_token": "bar"})
    print(f"no-convert x_token: {response.json()}")
    assert response.json() == {"x_token": "bar"}

    # Should NOT accept x-token
    response = client.get("/no-convert", headers={"x-token": "foo"})
    print(f"no-convert x-token: {response.json()}")
    assert response.json() == {"x_token": None}

if __name__ == "__main__":
    try:
        test_underscore_header_accepted()
        print("test_underscore_header_accepted passed")
    except AssertionError as e:
        print(f"test_underscore_header_accepted failed")

    try:
        test_underscore_header_not_accepted_when_disabled()
        print("test_underscore_header_not_accepted_when_disabled passed")
    except AssertionError as e:
        print(f"test_underscore_header_not_accepted_when_disabled failed")

